(7278622, 1133793, 43565, '<td valign="top">My observations: Did you mean "respectfully" instead of "respectively"? There is too much yellow for me. I know it''s a gold watch, but the color seems off. Lighting is a bit harsh, creating blown out spots and distracting shadows.</td>', 'My observations: Did you mean "respectfully" instead of "respectively"? There is too much yellow for me. I know it''s a gold watch, but the color seems off. Lighting is a bit harsh, creating blown out spots and distracting shadows.', '2014-10-31 11:58:30.000000', NULL, 1),
(7278623, 1133963, 43565, '<td valign="top">While this shows the detail in the ring, to me it loses impact as an advertisement. Maybe more detail in the shadows would help.</td>', 'While this shows the detail in the ring, to me it loses impact as an advertisement. Maybe more detail in the shadows would help.', '2014-10-31 12:00:10.000000', NULL, 1),
(7278624, 1133957, 43565, '<td valign="top">Like the duotone and streaks of sunlight. This does not work as a jewelry advertisement for me.</td>', 'Like the duotone and streaks of sunlight. This does not work as a jewelry advertisement for me.', '2014-10-31 12:01:24.000000', NULL, 1),
