(7278712, 1133963, 96751, '<td valign="top">Cool ring!!!</td>', 'Cool ring!!!', '2014-10-31 17:01:59.000000', NULL, 1),
(7278713, 1133530, 96751, '<td valign="top">What a beautiful photo!!!  LOVE the lighting, and how the weight of the ring seems to weigh on the horse''s head. I''m not sure about the smudgy rear outer leg, and I don''t think this shows off the ring to IT''s greatest advantage, but I love this image.</td>', 'What a beautiful photo!!!  LOVE the lighting, and how the weight of the ring seems to weigh on the horse''s head. I''m not sure about the smudgy rear outer leg, and I don''t think this shows off the ring to IT''s greatest advantage, but I love this image.', '2014-10-31 17:05:26.000000', NULL, 1),
(7278714, 1133986, 96751, '<td valign="top">This SO appeals to my love for the quirk!!!!! Perfect backdrop and colors. From a technical pov, I find the brightness of the hand draws away from the very delicate jewelry.I expect to find this on the front page.</td>', 'This SO appeals to my love for the quirk!!!!! Perfect backdrop and colors. From a technical pov, I find the brightness of the hand draws away from the very delicate jewelry.I expect to find this on the front page.', '2014-10-31 17:07:12.000000', NULL, 1),
(7278715, 1133976, 96751, '<td valign="top">Lovely</td>', 'Lovely', '2014-10-31 17:07:34.000000', NULL, 1),
(7278716, 1133565, 96751, '<td valign="top">This wins most awesomely bizarre entry</td>', 'This wins most awesomely bizarre entry', '2014-10-31 17:08:12.000000', NULL, 1),
(7278717, 1133662, 96751, '<td valign="top">Colors are lovely, but the bg is too distracting to me</td>', 'Colors are lovely, but the bg is too distracting to me', '2014-10-31 17:08:31.000000', NULL, 1),
(7278718, 1133837, 96751, '<td valign="top">Lovely blue and pretty good light, but the composition doesn''t work for me, and I don''t think this is the most flattering position to sell this piece.</td>', 'Lovely blue and pretty good light, but the composition doesn''t work for me, and I don''t think this is the most flattering position to sell this piece.', '2014-10-31 17:09:26.000000', NULL, 1),
