(7278736, 1133759, 96751, '<td valign="top">Killer bokeh!</td>', 'Killer bokeh!', '2014-10-31 17:20:31.000000', NULL, 1),
(7278741, 1133819, 63218, '<td valign="top">This is delicious. As luck would have it, my screen displayed it all at once--I only had to scroll to add comments. I admire the light, the motion, the subtle color, the motion, the detail, the motion. Yum. I wish this was mine.<br/> <br/>That being said, I would be very pleasantly surprised to see this used in an advertisement. But no retailer is that brave. So while it''s probably an epic fail as an advertisement, I do not consider this DNMC. You didn''t try to make up for it''s lack of mainstream-ness by some thoughtful text, for which I am grateful. It stands all on its own very nicely. So, thanks.</td>', 'This is delicious. As luck would have it, my screen displayed it all at once--I only had to scroll to add comments. I admire the light, the motion, the subtle color, the motion, the detail, the motion. Yum. I wish this was mine. That being said, I would be very pleasantly surprised to see this used in an advertisement. But no retailer is that brave. So while it''s probably an epic fail as an advertisement, I do not consider this DNMC. You didn''t try to make up for it''s lack of mainstream-ness by some thoughtful text, for which I am grateful. It stands all on its own very nicely. So, thanks.', '2014-10-31 18:58:52.000000', NULL, 1),
(7278751, 1133986, 43565, '<td valign="top">A different idea, but it works well. One of my favorites!</td>', 'A different idea, but it works well. One of my favorites!', '2014-10-31 20:39:37.000000', NULL, 1),
