(7279562, 1133662, 13077, '<td valign="top">Nice. Good color scheme, nice clean photos used and attractive layout and lettering.</td>', 'Nice. Good color scheme, nice clean photos used and attractive layout and lettering.', '2014-11-03 10:24:03.000000', NULL, 1),
(7279565, 1133624, 13077, '<td valign="top">Nice. Intriguing and classy.</td>', 'Nice. Intriguing and classy.', '2014-11-03 10:27:56.000000', NULL, 1),
