(7279909, 1133973, 159196, '<td valign="top">Beautifully done in every respect - in my top 5</td>', 'Beautifully done in every respect - in my top 5', '2014-11-04 19:15:53.000000', NULL, 1),
(7279910, 1133530, 159196, '<td valign="top">Love the mood and simplicity of this - I think that the font doesn''t quite marry with the rest, but nevertheless, this is in my top three!</td>', 'Love the mood and simplicity of this - I think that the font doesn''t quite marry with the rest, but nevertheless, this is in my top three!', '2014-11-04 19:18:29.000000', NULL, 1),
(7279911, 1133925, 159196, '<td valign="top">I''d buy this! In my top 5</td>', 'I''d buy this! In my top 5', '2014-11-04 19:20:41.000000', NULL, 1),
(7279912, 1133949, 159196, '<td valign="top">Well executed - it looks like a real ad from a glossy magazine! In my top 5</td>', 'Well executed - it looks like a real ad from a glossy magazine! In my top 5', '2014-11-04 19:22:40.000000', NULL, 1),
(7279913, 1133758, 159196, '<td valign="top">Great idea, and beautiful cat, but I feel that the jewel competes for attention with the cat''s eyes. For me the jewelry could be sharper and have more sparkle. In my top 5.</td>', 'Great idea, and beautiful cat, but I feel that the jewel competes for attention with the cat''s eyes. For me the jewelry could be sharper and have more sparkle. In my top 5.', '2014-11-04 19:29:20.000000', NULL, 1),
(7279938, 1133758, 30982, '<td valign="top">The photography is excellent - amazing detail on the cat''s face and eyes, which is tough on a black cat!  Not thrilled with the words.  For me, the picture alone would have been even better.</td>', 'The photography is excellent - amazing detail on the cat''s face and eyes, which is tough on a black cat!  Not thrilled with the words.  For me, the picture alone would have been even better.', '2014-11-04 21:30:46.000000', NULL, 1),
(7279939, 1133987, 30982, '<td valign="top">Very tastefully done - nice touchwith the purple lettering.  Could even have left off the "Starting at" bit and had a cleaner ad.</td>', 'Very tastefully done - nice touchwith the purple lettering.  Could even have left off the "Starting at" bit and had a cleaner ad.', '2014-11-04 21:31:27.000000', NULL, 1),
(7279940, 1133662, 30982, '<td valign="top">Can''t quite tell what the background is, and for some reason, that''s bothersome in an add.  Nice light and detail on the watch.</td>', 'Can''t quite tell what the background is, and for some reason, that''s bothersome in an add.  Nice light and detail on the watch.', '2014-11-04 21:32:19.000000', NULL, 1),
(7279941, 1133530, 30982, '<td valign="top">Very nice processing.  I may have preferred it without the words, but I understand it is to be an ad.</td>', 'Very nice processing.  I may have preferred it without the words, but I understand it is to be an ad.', '2014-11-04 21:33:34.000000', NULL, 1),
(7279942, 1134017, 30982, '<td valign="top">I like how well the theme (dangerous, can''t be tamed) is relfected in the photography.  Some may want the bracelet more focused, but I think it''s fine as is - works well with the whole ad this way.</td>', 'I like how well the theme (dangerous, can''t be tamed) is relfected in the photography.  Some may want the bracelet more focused, but I think it''s fine as is - works well with the whole ad this way.', '2014-11-04 21:35:13.000000', NULL, 1),
(7279943, 1133973, 30982, '<td valign="top">Very elegant!  I like the fascination of the cat.</td>', 'Very elegant!  I like the fascination of the cat.', '2014-11-04 21:35:49.000000', NULL, 1),
(7279944, 1133624, 30982, '<td valign="top">Gorgeous lighting.  Fun use of the flood thingie.</td>', 'Gorgeous lighting.  Fun use of the flood thingie.', '2014-11-04 21:36:04.000000', NULL, 1),
(7279946, 1133759, 30982, '<td valign="top">Natural and real - very nice!</td>', 'Natural and real - very nice!', '2014-11-04 21:36:15.000000', NULL, 1),
